import { Project, Task, User } from "../domain/entities";
import {
  ProjectRepository,
  TaskFilter,
  TaskRepository,
  UserRepository,
} from "../domain/repositories";

export class InMemoryUserRepository implements UserRepository {
  private readonly users = new Map<string, User>();
  public add(user: User): void { this.users.set(user.id, user); }
  public findById(id: string): User | undefined { return this.users.get(id); }
}

export class InMemoryProjectRepository implements ProjectRepository {
  private readonly projects = new Map<string, Project>();
  public add(project: Project): void { this.projects.set(project.id, project); }
  public findById(id: string): Project | undefined { return this.projects.get(id); }
}

export class InMemoryTaskRepository implements TaskRepository {
  private readonly tasks = new Map<string, Task>();
  public add(task: Task): void { this.tasks.set(task.id, task); }
  public findById(id: string): Task | undefined { return this.tasks.get(id); }
  public save(task: Task): void { this.tasks.set(task.id, task); }
  public findByProjectId(projectId: string, filter: TaskFilter = {}): Task[] {
    return [...this.tasks.values()].filter((task) =>
      task.projectId === projectId &&
      (filter.status === undefined || task.status === filter.status) &&
      (filter.assigneeId === undefined || task.assigneeId === filter.assigneeId),
    );
  }
}

